const field=(id,label,type='text',group='main',extra={})=>({id,label,type,group,...extra});
const group=(id,title,description)=>({id,title,...description?{description}:{}});
const options=values=>values.map(value=>typeof value==='string'?{value,label:value}:{value:value[0],label:value[1]});
const action=(section,name,label,extra={})=>({id:section+'.'+name,label,kind:'action',fields:[],...extra});
const save=section=>action(section,'save','Save changes',{kind:'save',fields:undefined});
const model=(section,groups,fields,values,actions=[save(section)],extra={})=>({section,revision:'rev-1',groups,fields,values,actions,capabilities:{write:true},...extra});

